\begin{axis}[width=7cm,height=6cm,axis lines=middle,axis line style={black},xlabel={$x$},ylabel={$y$},label style={font=\fontsize{10}{12}\selectfont,text=black},xmin=-1.8,xmax=3.8,ymin=-7,ymax=5,xtick=\empty,ytick=\empty,clip=false]
