\begin{axis}[width=7cm,height=6cm,axis lines=middle,axis line style={black},xlabel={$x$},ylabel={$y$},label style={font=\fontsize{10}{12}\selectfont,text=black},xmin=-3.3,xmax=3.3,ymin=-5,ymax=28,xtick=\empty,ytick=\empty,clip=false]
