\begin{axis}[width=7cm,height=6cm,axis lines=middle,axis line style={black},xlabel={$x$},ylabel={$y$},label style={font=\fontsize{10}{12}\selectfont,text=black},xmin=-3.2,xmax=3.6,ymin=-20,ymax=36,xtick=\empty,ytick=\empty,clip=false]
